<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\ValueObject\Accessor\UserConsentedScopesTrustedClientAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserConsentedScopesTrustedClientAccessor trait.
 *
 * Covers null default, string/VO assignment via withTrustedClient,
 * getTrustedClient/trustedClient accessors, and isTrustedClientChanged with/without original.
 */
class UserConsentedScopesTrustedClientAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTrustedClient creates a new instance with the TrustedClient set
     * from a string value, and getTrustedClient returns the primitive string.
     */
    public function testWithTrustedClientFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentedScopesTrustedClientAccessorUnitTest();

        // Act
        $result = $holder->withTrustedClient(new TrustedClientRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new TrustedClientRef('one'), $result->getTrustedClient());
    }
    /**
     * Asserts that withtrustedClient has access to the value object
     * from a string value, and getTrustedClient returns the primitive string.
     */
    public function testWithTrustedClientFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentedScopesTrustedClientAccessorUnitTest();

        // Act
        $result = $holder->withTrustedClient(new TrustedClientRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new TrustedClientRef('one'), $result->trustedClient()->value());
    }
    public function testChangedTrustedClient(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentedScopesTrustedClientAccessorUnitTest()->withTrustedClient(new TrustedClientRef('one'));
        $original = $holder->withTrustedClient(new TrustedClientRef('one'));
        $same = $holder->withTrustedClient(new TrustedClientRef('one'));
        $modified = $holder->withTrustedClient(new TrustedClientRef('other'));

        // Act
        $withSame = $original->isTrustedClientChanged($same);
        $withDiferent = $original->isTrustedClientChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserConsentedScopesTrustedClientAccessorUnitTest
{
    use UserConsentedScopesTrustedClientAccessor;
}
